function safeParse(value,fallback){try{return value?JSON.parse(value):fallback}catch{return fallback}}
/* Version 7.5.1 — hardened local data transfer */
const LOCAL_DATA_STAMP_KEY='ddmg-local-data-last-changed';
const LOCAL_DATA_PROFILE_KEY='ddmg-local-data-profile';
function stampLocalDataChange(reason='local change'){
 try{
  const payload={at:new Date().toISOString(),reason,version:'7.5.1'};
  localStorage.setItem(LOCAL_DATA_STAMP_KEY,JSON.stringify(payload));
  localStorage.setItem(LOCAL_DATA_PROFILE_KEY,'Local browser/app storage');
 }catch(e){}
}
function getLocalDataStamp(){
 try{
  const raw=localStorage.getItem(LOCAL_DATA_STAMP_KEY);
  if(!raw)return null;
  return JSON.parse(raw);
 }catch(e){return null}
}
function formatLocalStamp(stamp){
 if(!stamp||!stamp.at)return 'No local changes recorded yet';
 const d=new Date(stamp.at);
 if(Number.isNaN(d.getTime()))return 'Local change recorded, date unavailable';
 return `${d.toLocaleString()} · ${stamp.reason||'local change'}`;
}
function renderLocalDataStamp(){
 const stampEl=document.getElementById('localDataStamp');
 const profileEl=document.getElementById('localDataProfile');
 if(stampEl)stampEl.textContent=formatLocalStamp(getLocalDataStamp());
 if(profileEl)profileEl.textContent=localStorage.getItem(LOCAL_DATA_PROFILE_KEY)||'Local browser/app storage';
}
function exportLocalData(){
 const storage={};
 for(let i=0;i<localStorage.length;i++){
  const key=localStorage.key(i);
  if(key&&key.startsWith('ddmg-'))storage[key]=localStorage.getItem(key);
 }
 const data={exportedAt:new Date().toISOString(),app:'Don Downs Mountain Guide',version:'7.5.1',scope:'ddmg-localStorage-only',storage};
 const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});
 const url=URL.createObjectURL(blob);
 const a=document.createElement('a');
 a.href=url;
 a.download=`don-downs-mountain-guide-backup-${new Date().toISOString().slice(0,10)}.json`;
 document.body.appendChild(a);
 a.click();
 a.remove();
 setTimeout(()=>URL.revokeObjectURL(url),1000);
 stampLocalDataChange('exported backup from this device');
 renderLocalDataStamp();
}
function importLocalDataFile(file){
 const reader=new FileReader();
 reader.onload=()=>{
  try{
   const parsed=JSON.parse(String(reader.result||'{}'));
   const sourceStorage=parsed.storage&&typeof parsed.storage==='object'?parsed.storage:parsed;
   if(!sourceStorage||typeof sourceStorage!=='object')throw new Error('No storage object found');
   const entries=Object.entries(sourceStorage).filter(([key,value])=>key.startsWith('ddmg-')&&typeof value==='string');
   if(!entries.length)throw new Error('No Mountain Guide data keys found');
   const exportedAt=parsed.exportedAt?new Date(parsed.exportedAt):null;
   const dateLabel=exportedAt&&!Number.isNaN(exportedAt.getTime())?exportedAt.toLocaleString():'date unavailable';
   const confirmed=confirm(
    `Import Mountain Guide backup?\n\n`+
    `Backup date: ${dateLabel}\n`+
    `Mountain Guide data items: ${entries.length}\n\n`+
    `This will replace matching Mountain Guide data on this device and cannot be undone. `+
    `Use this only when you intend this backup to become the source of truth for this device.`
   );
   if(!confirmed)return;
   entries.forEach(([key,value])=>localStorage.setItem(key,value));
   stampLocalDataChange('imported backup file');
   renderLocalDataStamp();
   alert('Backup imported. The app will reload so every screen uses the imported data.');
   location.reload();
  }catch(e){
   alert('Import failed. The selected file was not a valid Mountain Guide backup.');
  }
 };
 reader.readAsText(file);
}
function setupDataTransferPanel(){
 const exportBtn=document.getElementById('exportDataBtn');
 const importFile=document.getElementById('importDataFile');
 if(exportBtn)exportBtn.addEventListener('click',exportLocalData);
 if(importFile)importFile.addEventListener('change',e=>{
  const file=e.target.files&&e.target.files[0];
  if(file)importLocalDataFile(file);
  e.target.value='';
 });
 renderLocalDataStamp();
}
document.addEventListener('DOMContentLoaded',setupDataTransferPanel);
function storageGet(key){try{return localStorage.getItem(key)}catch(error){console.warn('Storage read failed',key,error);return null}}
function storageSet(key,value){try{localStorage.setItem(key,value);if(key!==LOCAL_DATA_STAMP_KEY&&key!==LOCAL_DATA_PROFILE_KEY)stampLocalDataChange(`updated ${key}`);return true}catch(error){console.warn('Storage write failed',key,error);return false}}
function storageRemove(key){try{localStorage.removeItem(key);return true}catch(error){console.warn('Storage removal failed',key,error);return false}}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function locationById(id){return WEATHER_LOCATIONS.find(x=>x.id===id)||WEATHER_LOCATIONS[1]}
function ageHours(iso){return iso?(Date.now()-new Date(iso).getTime())/3600000:Infinity}
function daysTo(dateStr){const target=new Date(dateStr+'T00:00:00-06:00');return (target-Date.now())/86400000}
function parseWind(text=''){const nums=(String(text).match(/\d+/g)||[]).map(Number);return nums.length?Math.max(...nums):0}
function feet(meters){return Number.isFinite(meters)?Math.round(meters*3.28084):null}
function formatStamp(iso,includeDate=true){
 if(!iso)return 'Never';
 return new Intl.DateTimeFormat('en-US',{timeZone:'America/Denver',...(includeDate?{month:'short',day:'numeric'}:{}),hour:'numeric',minute:'2-digit'}).format(new Date(iso))
}
function denverParts(iso){
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Denver',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso));
 const o=Object.fromEntries(parts.map(p=>[p.type,p.value]));
 return {date:`${o.year}-${o.month}-${o.day}`,hour:Number(o.hour),minute:Number(o.minute)}
}
function hourLabel(iso){
 const d=new Date(iso);
 return new Intl.DateTimeFormat('en-US',{timeZone:'America/Denver',hour:'numeric'}).format(d).replace(' ','').toLowerCase()
}
function toast(message){
 const el=document.getElementById('toast'); if(!el)return;
 el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)
}

function countdown(){
 const now=new Date(),el=document.getElementById('countdown'),ms=TRIP_START-now;
 if(ms>0){const d=Math.floor(ms/86400000),h=Math.floor(ms%86400000/3600000),m=Math.floor(ms%3600000/60000);el.textContent=`${d}d ${h}h ${m}m`}
 else if(now<=TRIP_END)el.textContent='Expedition underway';
 else el.textContent='Expedition complete';
}
setInterval(countdown,30000);countdown();


